### LoginForm.tsx
```tsx
import { useState } from 'react';
import { EyeIcon, EyeOffIcon } from 'lucide-react';

export interface LoginFormProps {
  formState: {
    email: string;
    password: string;
    errors: {
      email?: string;
      password?: string;
    };
  };
  onInputChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
  onSubmit: (e: React.FormEvent) => void;
}

const LoginForm = ({
  formState,
  onInputChange,
  onSubmit,
}: LoginFormProps) => {
  const [showPassword, setShowPassword] = useState(false);

  const togglePasswordVisibility = () => {
    setShowPassword((prev) => !prev);
  };

  return (
    <form onSubmit={onSubmit} className="w-full max-w-md p-8 space-y-6 bg-white rounded-lg shadow-md">
      <div>
        <label htmlFor="email" className="block text-sm font-medium text-gray-700 mb-1">
          Email
        </label>
        <input
          id="email"
          name="email"
          type="email"
          value={formState.email}
          onChange={onInputChange}
          className={`w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-accent focus:outline-none transition-colors ${
            formState.errors.email ? 'border-red-300' : 'border-gray-300'
          }`}
          placeholder="your@email.com"
        />
        {formState.errors.email && (
          <p className="mt-1 text-sm text-red-500 flex items-center">
            <span>{formState.errors.email}</span>
          </p>
        )}
      </div>

      <div>
        <label htmlFor="password" className="block text-sm font-medium text-gray-700 mb-1">
          Password
        </label>
        <div className="relative">
          <input
            id="password"
            name="password"
            type={showPassword ? 'text' : 'password'}
            value={formState.password}
            onChange={onInputChange}
            className={`w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-accent focus:outline-none transition-colors ${
              formState.errors.password ? 'border-red-300' : 'border-gray-300'
            }`}
            placeholder="••••••••"
          />
          <button
            type="button"
            onClick={togglePasswordVisibility}
            className="absolute inset-y-0 right-0 flex items-center pr-3 text-gray-500 hover:text-gray-700"
          >
            {showPassword ? <EyeOffIcon size={18} /> : <EyeIcon size={18} />}
          </button>
        </div>
        {formState.errors.password && (
          <p className="mt-1 text-sm text-red-500 flex items-center">
            <span>{formState.errors.password}</span>
          </p>
        )}
      </div>

      <button
        type="submit"
        disabled={!formState.email || !formState.password}
        className={`w-full py-3 px-4 rounded-lg text-white font-medium transition-colors ${
          formState.email && formState.password
            ? 'bg-accent hover:bg-purple-600'
            : 'bg-gray-300 cursor-not-allowed'
        }`}
      >
        Sign In
      </button>
    </form>
  );
};

export { LoginForm };
```

